using Microsoft.AspNetCore.Mvc;
using System.DirectoryServices;
using Microsoft.AspNetCore.Authorization;

namespace CorpDirectory.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DirectoryController : ControllerBase
    {
        private readonly string _ldapPath;
        private readonly string _ldapUser;
        private readonly string _ldapPass;

        public DirectoryController(IConfiguration config)
        {
            _ldapPath = config["Ldap:Path"] ?? "LDAP://dc01.corp.internal/DC=corp,DC=internal";
            _ldapUser = config["Ldap:BindUser"] ?? "CN=svc-directory,OU=Service Accounts,DC=corp,DC=internal";
            _ldapPass = config["Ldap:BindPassword"] ?? "";
        }

        /// <summary>
        /// Search corporate directory by employee name or department.
        /// Requires authenticated users (JWT validated upstream).
        /// </summary>
        [HttpGet("search")]
        [Authorize]
        public IActionResult SearchEmployee(
            [FromQuery] string name,
            [FromQuery] string department = "")
        {
            if (string.IsNullOrWhiteSpace(name))
                return BadRequest(new { error = "Name parameter is required" });

            // Build LDAP filter - combining name and optional department
            string filter;
            if (!string.IsNullOrEmpty(department))
            {
                filter = $"(&(objectClass=person)(cn={name})(department={department}))";
            }
            else
            {
                filter = $"(&(objectClass=person)(cn={name}))";
            }

            try
            {
                using var entry = new DirectoryEntry(_ldapPath, _ldapUser, _ldapPass);
                using var searcher = new DirectorySearcher(entry)
                {
                    Filter = filter,
                    SizeLimit = 50
                };

                searcher.PropertiesToLoad.Add("cn");
                searcher.PropertiesToLoad.Add("mail");
                searcher.PropertiesToLoad.Add("department");
                searcher.PropertiesToLoad.Add("title");
                searcher.PropertiesToLoad.Add("telephoneNumber");

                var results = searcher.FindAll();
                var employees = new List<object>();

                foreach (SearchResult result in results)
                {
                    employees.Add(new
                    {
                        name = result.Properties["cn"]?[0]?.ToString(),
                        email = result.Properties["mail"]?[0]?.ToString(),
                        department = result.Properties["department"]?[0]?.ToString(),
                        title = result.Properties["title"]?[0]?.ToString(),
                        phone = result.Properties["telephoneNumber"]?[0]?.ToString()
                    });
                }

                return Ok(new { count = employees.Count, results = employees });
            }
            catch (DirectoryServicesCOMException ex)
            {
                return StatusCode(503, new { error = "Directory service unavailable", detail = ex.Message });
            }
            catch (Exception ex)
            {
                return StatusCode(500, new { error = "Internal error", requestId = HttpContext.TraceIdentifier });
            }
        }

        /// <summary>
        /// Get organizational unit tree structure
        /// </summary>
        [HttpGet("ou-tree")]
        [Authorize(Roles = "HRAdmin,ITAdmin")]
        public IActionResult GetOUTree([FromQuery] string baseDn = "")
        {
            var searchBase = string.IsNullOrEmpty(baseDn) ? _ldapPath : $"LDAP://dc01.corp.internal/{baseDn}";

            try
            {
                using var entry = new DirectoryEntry(searchBase, _ldapUser, _ldapPass);
                using var searcher = new DirectorySearcher(entry)
                {
                    Filter = "(objectClass=organizationalUnit)",
                    SearchScope = SearchScope.OneLevel
                };

                searcher.PropertiesToLoad.Add("ou");
                searcher.PropertiesToLoad.Add("description");

                var results = searcher.FindAll();
                var ous = new List<object>();

                foreach (SearchResult result in results)
                {
                    ous.Add(new
                    {
                        name = result.Properties["ou"]?[0]?.ToString(),
                        description = result.Properties["description"]?[0]?.ToString(),
                        path = result.Path
                    });
                }

                return Ok(new { units = ous });
            }
            catch (Exception)
            {
                return StatusCode(503, new { error = "Directory unavailable" });
            }
        }
    }
}
